import * as esbuild from "esbuild";

async function bundle(entry, outfile, banner) {
  await esbuild.build({
    entryPoints: [entry],
    bundle: true,
    minify: true,
    format: "iife",
    platform: "browser",
    target: ["es2020"],
    jsx: "automatic",
    outfile,
    legalComments: "none",
    define: {
      "process.env.NODE_ENV": '"production"',
    },
    banner: { js: banner },
  });
}

await bundle(
  "login.jsx",
  "../../app/privy-login.js",
  "/* Wakeloom Privy login. Built from tools/privy-login. Do not edit this file. */",
);
await bundle(
  "fund.jsx",
  "../../app/privy-fund.js",
  "/* Wakeloom Privy fundWallet. Built from tools/privy-login. Do not edit this file. */",
);
